using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// IMGS REFL and RDIF are Reflection objects (RDIF's parent pointer is a FormLink). A whole record from Starfield.esm,
// both readers, written back byte for byte; and an RDIF over 64 KB (XXXX) read and written with both readers.
public class ImageSpaceReflectionTests
{
    private static void WritesBack(IStarfieldMajorRecordGetter rec, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(w => rec.WriteToBinary(w)));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    // ISExteriorUniqueAkilaRainDay01 (0DB200:Starfield.esm)
    private const string AkilaRainDayHex = "";

    [Fact]
    public void AkilaRainDay()
    {
        foreach (var rec in ReadBoth<IImageSpaceGetter>(Record("IMGS", Hex(AkilaRainDayHex)), f => ImageSpace.CreateFromBinary(f), (s, p) => ImageSpaceBinaryOverlay.ImageSpaceFactory(s, p)))
        {
            rec.Reflection.ShouldBeNull();
            // ISExteriorRainDay01 (0E83A6:Starfield.esm)
            rec.ReflectionDiff.ShouldHaveFormIds(0x0E83A6);
            rec.ReflectionDiff.RootObject().Class.Name.ShouldBe("TESImageSpace");
            rec.ReflectionParent.FormKey.ID.ShouldBe(0x0E83A6u);
            WritesBack(rec, AkilaRainDayHex);
        }
    }

    // A Reflection behind a record type override (RDIF) with an overflow: the length comes from XXXX in both readers
    // and the writer puts the XXXX back.
    [Fact]
    public void ReflectionDiffOverflow()
    {
        var payload = Enumerable.Range(0, ushort.MaxValue + 100).Select(i => (byte)(i * 7)).ToArray();
        var body = new MemoryStream();
        body.Write(Subrecord("EDID", System.Text.Encoding.ASCII.GetBytes("Test\0")));
        body.Write(Subrecord("XXXX", BitConverter.GetBytes(payload.Length)));
        body.Write(System.Text.Encoding.ASCII.GetBytes("RDIF"));
        body.Write(BitConverter.GetBytes((ushort)0));
        body.Write(payload);
        var content = body.ToArray();
        foreach (var rec in ReadBoth<IImageSpaceGetter>(Record("IMGS", content), f => ImageSpace.CreateFromBinary(f), (s, p) => ImageSpaceBinaryOverlay.ImageSpaceFactory(s, p)))
        {
            rec.EditorID.ShouldBe("Test");
            rec.ReflectionDiff!.Data.ToArray().ShouldBe(payload);
            rec.ReflectionDiff.FormLinks.ShouldBeEmpty();
            GameConstants.Starfield.MajorRecord(Write(w => rec.WriteToBinary(w))).Content.ToArray().ShouldBe(content);
        }
    }
}
